// The nav icons come from the C app's apps/home_icons.h, so they are written
// down once: each `static const unsigned char ic_<name>[] = {...};` becomes a
// `const IC_<NAME>: [u8; N]` in $OUT_DIR/icons.rs, with ICON_SZ beside them.
use std::{env, fs, path::PathBuf};

fn main() {
    let header = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap()).join("../../home_icons.h");
    let text = fs::read_to_string(&header).expect("apps/home_icons.h");
    let mut out = String::from(
        "// Generated by apps/xpui/home/build.rs from apps/home_icons.h. Do not edit.\n",
    );
    for line in text.lines() {
        if let Some(size) = line.strip_prefix("#define ICON_SZ ") {
            out.push_str(&format!("const ICON_SZ: i32 = {};\n", size.trim()));
        } else if let Some(rest) = line.strip_prefix("static const unsigned char ic_") {
            let (name, bytes) = rest.split_once("[] = {").expect("an icon array");
            let bytes = bytes.trim_end_matches("};").trim();
            let n = bytes.split(',').filter(|b| !b.trim().is_empty()).count();
            out.push_str(&format!(
                "const IC_{}: [u8; {n}] = [{bytes}];\n",
                name.to_uppercase()
            ));
        }
    }
    fs::write(
        PathBuf::from(env::var("OUT_DIR").unwrap()).join("icons.rs"),
        out,
    )
    .unwrap();
    println!("cargo:rerun-if-changed={}", header.display());
}
